WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-EC-011-04', 'systemic_abuse_intelligence', 311, 'hospice_care_complaint', 'hospice_complaint_routes', 'federal + state', 'federal + state -- ALL_STATES', 'Where to Complain -- Three Bodies With Different Powers', 'federal_agency | state_survey_agency | federal_program', 'hospice_complaint_routes', 'https://www.medicare.gov/care-compare/', 'Your Medicare BFCC-QIO | Your state survey agency -- see jurisdiction table | Long-Term Care Ombudsman: 800-677-1116 | Medicare: 800-633-4227', 'Hospice Conditions of Participation (42 CFR Part 418) | Survey and certification (42 CFR Part 488) | QIO functions and beneficiary complaints (42 CFR Part 476) | LTC Ombudsman (42 U.S.C. sec. 3058g) | Elder Justice Act crime reporting (42 U.S.C. sec. 1320b-25)', 'VERIFIED', '2026-08-17', 'FILE WITH THE QIO AND THE STATE SURVEY AGENCY BOTH. The QIO produces an independent PHYSICIAN review of the clinical care -- something no other route here delivers -- while the survey agency is the only body that can cite the hospice and threaten its Medicare certification. If the patient is in a facility, add the Ombudsman: two sets of rights are running at once and failures routinely fall into the gap between them. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-011 | pipeline: Hospice Care Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 3b480a06fcb8439b9352bc2f5d9c5584b19a794b2541adad6205f19acf9c5218]', 'v1.0'),
('SAIS-EC-011-05', 'systemic_abuse_intelligence', 311, 'hospice_care_complaint', 'hospice_records_and_evidence', 'federal + state', 'federal + state -- ALL_STATES', 'Records and Evidence -- Building the Symptom and Response Timeline', 'federal_agency | state_court', 'hospice_records_and_evidence', 'https://www.hhs.gov/hipaa/for-individuals/medical-records/index.html', 'HHS Office for Civil Rights (records access): 800-368-1019 | The hospice''s records department | Your state bar lawyer referral service', 'HIPAA right of access and personal representatives (45 CFR 164.524; 45 CFR 164.502(g)) | Hospice clinical records (42 CFR 418.104) | Interdisciplinary group review requirement (42 CFR 418.56(d)) | State wrongful death and survival statutes.', 'VERIFIED', '2026-08-17', 'REQUEST THE ON-CALL LOG BY NAME. The single most common hospice complaint is that no one responded overnight, 24-hour nursing availability is a federal requirement, and the call log settles the question definitively -- but it is retained on a short schedule and is almost never produced unless specifically demanded. Send the preservation letter the same week you request records. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-011 | pipeline: Hospice Care Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 3303c5937c965a2de3e02bbf2575fd179dca90bfad7a174aaf8e3459e065a26b]', 'v1.0'),
('SAIS-EC-011-06', 'systemic_abuse_intelligence', 311, 'hospice_care_complaint', 'hospice_bereavement_and_billing', 'federal', 'federal -- NATIONWIDE', 'After the Death -- Bereavement Services, Billing Review, and Fraud Referral', 'federal_agency | federal_program', 'hospice_bereavement_and_billing', 'https://www.smpresource.org/', 'Senior Medicare Patrol: 877-808-2468 | HHS Office of Inspector General Hotline: 800-447-8477 | Medicare: 800-633-4227 | Eldercare Locator: 800-677-1116', 'Bereavement counseling requirement (42 CFR 418.64(d)) | Hospice payment and levels of care (42 CFR 418.302) | False Claims Act (31 U.S.C. sec. 3729 et seq.) | Senior Medicare Patrol (Older Americans Act, 42 U.S.C. sec. 3001 et seq.) | Medicaid Fraud Control Units (42 U.S.C. sec. 1396b(q))', 'VERIFIED', '2026-08-17', 'CALL THE HOSPICE AND ASK FOR THE BEREAVEMENT COORDINATOR -- counseling for the family for AT LEAST ONE YEAR after the death is a federal requirement at no additional charge, and most families are never meaningfully told. Then call the SENIOR MEDICARE PATROL at 877-808-2468 for free help reviewing the Medicare statements; billing a higher level of care than was delivered is the signature hospice fraud pattern and it is visible in the paperwork. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-011 | pipeline: Hospice Care Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f5eaa2625baafe4fe30560b4a4c74b8e483ea38a42138c19c47cdfe236bf460e]', 'v1.0'),
('SAIS-FC-001', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_custody_family_court', 'state', 'state -- ALL_STATES', 'Custody and Family Court -- Building a Record the Court Can Actually Use', 'state_court | legal_aid', 'family_custody_family_court', 'https://www.lawhelp.org/', 'Your state court self-help center -- see jurisdiction table | Dial 211 for local family law facilitators', 'Uniform Child Custody Jurisdiction and Enforcement Act (UCCJEA, adopted in 49 states) | Parental Kidnapping Prevention Act (28 U.S.C. sec. 1738A) | Violence Against Women Act (34 U.S.C. sec. 12291) | State best-interests statutes.', 'VERIFIED', '2026-08-17', 'START THE WRITTEN LOG TODAY AND MOVE CO-PARENTING COMMUNICATION TO A SINGLE WRITTEN CHANNEL. The parent with the contemporaneous record generally prevails on contested factual questions. If domestic violence is part of the history, say so explicitly and early -- most states have a statutory presumption that must be invoked to operate. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: cc156fe1d63dec830e76893873d5c43e44007bd2ac1188d97c7a1e51689180e2]', 'v1.0'),
('SAIS-FC-002', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_domestic_violence_documentation', 'federal + state', 'federal + state -- ALL_STATES', 'Domestic Violence Documentation -- Building the Record Without Increasing Risk', 'state_court | victim_services | federal_program', 'family_domestic_violence_documentation', 'https://www.thehotline.org/', 'National Domestic Violence Hotline: 800-799-7233 | TTY 800-787-3224 | Text START to 88788 | Dial 211 for local shelters', 'Violence Against Women Act (34 U.S.C. sec. 12291 et seq.) | Victims of Crime Act (34 U.S.C. sec. 20101 et seq.) | Full Faith and Credit for protection orders (18 U.S.C. sec. 2265) | Address confidentiality and state DV statutes.', 'VERIFIED', '2026-08-17', 'PROTECTION ORDERS ARE ENFORCEABLE IN EVERY STATE AND TERRITORY UNDER FEDERAL FULL FAITH AND CREDIT, WITHOUT REREGISTRATION. An order obtained in one state does not stop working at the state line. Before creating documentation, check where it will be stored and who else can reach it -- a safety-planning advocate can help set this up, and the National Domestic Violence Hotline can connect you to one at any hour. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 057e4e02b28f6844d161ad7c695d97ff9cf549d1b81ad2dada763dbd29bfbcdf]', 'v1.0'),
('SAIS-FC-003', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_child_welfare_investigation', 'state', 'state -- ALL_STATES', 'Child Welfare Investigation -- What Rights Exist When CPS Is Involved', 'state_agency | state_court | legal_aid', 'family_child_welfare_investigation', 'https://www.childwelfare.gov/', 'Your state child welfare agency -- see jurisdiction table | Childhelp National Child Abuse Hotline: 800-422-4453 | Dial 211 for local parent advocacy', 'Adoption and Safe Families Act (42 U.S.C. sec. 671 et seq.) | Child Abuse Prevention and Treatment Act (42 U.S.C. sec. 5101 et seq.) | Indian Child Welfare Act (25 U.S.C. sec. 1901 et seq.) | Fostering Connections Act relative notice requirement | State juvenile codes.', 'VERIFIED', '2026-08-17', 'ASK ABOUT INDIAN CHILD WELFARE ACT APPLICABILITY AT THE FIRST HEARING IF THE CHILD MAY HAVE ANY TRIBAL ANCESTRY. ICWA imposes heightened standards, placement preferences, and tribal notice requirements, and failure to inquire is a recognized ground to overturn later orders. Separately: do not sign a safety plan or voluntary placement agreement without asking whether it is voluntary and what declining means -- these documents move children without any judicial finding. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0be49d48793e5bd17c401b3206cb68f542fe5ca0252735f83c1d74f3b6cf678b]', 'v1.0'),
('SAIS-FC-004', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_foster_care_records', 'state', 'state -- ALL_STATES', 'Foster Care Records -- Getting the File and Correcting What It Says', 'state_agency | state_court', 'family_foster_care_records', 'https://www.childwelfare.gov/topics/outofhome/', 'Your state child welfare agency records unit -- see jurisdiction table | Dial 211 for local foster youth advocacy', 'Adoption and Safe Families Act (42 U.S.C. sec. 671) | Fostering Connections to Success Act | John H. Chafee Foster Care Program for Successful Transition to Adulthood (42 U.S.C. sec. 677) | Consumer credit report requirement (42 U.S.C. sec. 675(5)(I)) | State child welfare records statutes.', 'VERIFIED', '2026-08-17', 'REQUEST THE FILE IN ITEMIZED FORM, NOT AS A GENERAL REQUEST. Agencies produce what is specifically named. The placement history, the credit report, and the education transcript are the three items most often omitted and most often needed. For any youth 14 or older, the free annual credit report and assistance clearing inaccuracies is a federal entitlement, not a courtesy. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 472f1048fc54682cb57cd460bbb3537139998a6ed39f1fdb5091da4456c37344]', 'v1.0'),
('SAIS-FC-005', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_child_support_enforcement', 'federal + state', 'federal + state -- ALL_STATES', 'Child Support Enforcement -- Free State Enforcement and the Modification Trap', 'state_agency | federal_program', 'family_child_support_enforcement', 'https://www.acf.hhs.gov/css', 'Your state child support enforcement agency -- see jurisdiction table | Federal Office of Child Support Services', 'Title IV-D of the Social Security Act (42 U.S.C. sec. 651 et seq.) | Uniform Interstate Family Support Act (UIFSA, adopted nationwide) | Bankruptcy Code sec. 523(a)(5) (support nondischargeable) | Federal offset and passport denial programs.', 'VERIFIED', '2026-08-17', 'FILE THE MODIFICATION PETITION THE WEEK INCOME CHANGES. This is the highest-consequence, lowest-effort action in this entire category. Retroactive modification is barred in almost every state, arrears are not dischargeable in bankruptcy, and interest accrues in many states. For receiving parents: Title IV-D services are free or near-free and reach enforcement tools no private attorney can access, including federal tax refund interception. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: deea35205616abdcaaefd7af17cd2714ec201df8f39fb690ccc02d9839e00795]', 'v1.0'),
('SAIS-FC-006', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_adoption_records', 'state', 'state -- ALL_STATES', 'Adoption Records -- Access to Original Records and Identifying Information', 'state_agency | state_court | state_vital_records', 'family_adoption_records', 'https://www.childwelfare.gov/topics/systemwide/laws-policies/statutes/', 'Your state vital records office -- see jurisdiction table | State adoption registry | Your state''s mutual consent reunion registry', 'Indian Child Welfare Act (25 U.S.C. sec. 1901 et seq.; sec. 1917 tribal information right) | State adoption records and original birth certificate access statutes | State mutual consent registry statutes | State vital records acts.', 'VERIFIED', '2026-08-17', 'VERIFY YOUR STATE''S CURRENT RULE RATHER THAN RELYING ON WHAT WAS TRUE PREVIOUSLY -- original birth certificate access has expanded in a substantial number of states in recent years and continues to change. Register with the state mutual consent registry regardless of which route you pursue; it is low-cost, passive, and works in the background. Request non-identifying medical history first, since it is the least restricted and often the actual need. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ee2a2cdece7955a76bd5ee804cc4605e7c899d53a1eeb258c91dfd761b735016]', 'v1.0'),
('SAIS-FC-007', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_parental_rights_termination', 'state', 'state -- ALL_STATES', 'Parental Rights Termination -- Standard of Proof, Counsel, and Expedited Appeal', 'state_court | legal_aid', 'family_parental_rights_termination', 'https://www.childwelfare.gov/topics/permanency/', 'Your state child welfare agency -- see jurisdiction table | Court-appointed counsel through the juvenile court | Dial 211 for parent advocacy programs', 'Adoption and Safe Families Act (42 U.S.C. sec. 675(5)(E)) | Indian Child Welfare Act (25 U.S.C. sec. 1912(f) beyond-a-reasonable-doubt standard; active efforts) | Santosky v. Kramer (clear and convincing evidence constitutionally required) | State termination statutes.', 'VERIFIED', '2026-08-17', 'PRESERVE THE APPEAL THE DAY THE ORDER ENTERS. Termination appeals are expedited and the window can be as short as 20 days -- shorter than the time it typically takes to find new counsel. Filing a notice of appeal preserves the right; the brief comes later. If there is any tribal ancestry, raise ICWA immediately: it raises the burden of proof to beyond a reasonable doubt and requires active efforts and qualified expert testimony. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 9be4255cdcf70825a742cdf7637e356666dc119acc80900ed7f8b91f91af5c3a]', 'v1.0'),
('SAIS-FC-008', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_juvenile_justice', 'state', 'state -- ALL_STATES', 'Juvenile Justice -- Counsel, Detention, and Record Sealing', 'state_court | public_defender', 'family_juvenile_justice', 'https://www.ojjdp.gov/', 'Your state public defender or juvenile defender office -- see jurisdiction table | National Juvenile Defender resources | Dial 211', 'In re Gault (right to counsel and due process in juvenile proceedings) | In re Winship (proof beyond a reasonable doubt) | Juvenile Justice and Delinquency Prevention Act (34 U.S.C. sec. 11101 et seq.) | State juvenile codes and sealing statutes.', 'VERIFIED', '2026-08-17', 'JUVENILE RECORDS ARE NOT AUTOMATICALLY SEALED IN MOST STATES. This is the single most damaging misconception in this pathway. Calendar the sealing eligibility date at case closure and file the petition when it arrives -- unsealed records surface in background checks years later, when the person has no idea why they were screened out. Never permit questioning without counsel, including by a school resource officer. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: c265864ed9a537d1a7ee6f9b50a5e3caa99e8bbc6ef2298adcc956f5b5dcf21f]', 'v1.0'),
('SAIS-FC-009', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_court_general', 'state', 'state -- ALL_STATES', 'Family Court General -- Navigating Without a Lawyer', 'state_court | legal_aid', 'family_court_general', 'https://www.lawhelp.org/', 'Your state court self-help center -- see jurisdiction table | LawHelp.org for state-specific forms | Dial 211 for court navigators', 'State rules of family and civil procedure | State court fee waiver statutes | Title 42 access-to-justice provisions | Court interpreter requirements under Title VI (42 U.S.C. sec. 2000d) and state law.', 'VERIFIED', '2026-08-17', 'ASK THE CLERK FOR THE FEE WAIVER FORM AND WHETHER A SELF-HELP CENTER OR FACILITATOR EXISTS BEFORE SPENDING ANYTHING. Both are free, both are widely available, and neither is routinely offered. Then ask whether attorneys in your state may be retained for limited scope representation -- one hour of document review before a hearing frequently changes the outcome at a fraction of full representation cost. Get every agreement entered as an order; an unentered agreement is unenforceable. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: addcede9356d0284d6d573cb44f35c9e123404733fffd50c9c7192c1bc7c2d52]', 'v1.0'),
('SAIS-FC-010', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_guardianship_dispute', 'state', 'state -- ALL_STATES', 'Guardianship Dispute -- Contesting, Narrowing, and Terminating a Guardianship', 'state_court', 'family_guardianship_dispute', 'https://www.americanbar.org/groups/law_aging/', 'Your state court self-help center -- see jurisdiction table | ABA Commission on Law and Aging: 202-662-8690', 'Uniform Guardianship, Conservatorship, and Other Protective Arrangements Act (2017, adopted in a growing number of states) | Uniform Power of Attorney Act (2006) | Americans with Disabilities Act (42 U.S.C. sec. 12101) | State guardianship and supported decision-making statutes.', 'VERIFIED', '2026-08-17', 'ASK ABOUT LESS RESTRICTIVE ALTERNATIVES EXPLICITLY, BY NAME, AND BEFORE ANY ORDER ENTERS. Courts in nearly every state must consider them, but families and even some attorneys treat plenary guardianship as the safe default. If a guardianship is already in place and is too broad, a petition to narrow or terminate can be filed at any time -- the window never closes. Where mismanagement is suspected, the petition to compel an accounting is faster than proving abuse. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: cb608b8f7c7d39f3f080b098216ea750882418abdac5973f118d4c32775d61a8]', 'v1.0'),
('SAIS-FC-011', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_paternity_dispute', 'state', 'state -- ALL_STATES', 'Paternity Dispute -- Acknowledgment, Genetic Testing, and the Rescission Window', 'state_agency | state_court', 'family_paternity_dispute', 'https://www.acf.hhs.gov/css/outreach-material/establishing-paternity', 'Your state child support enforcement agency -- see jurisdiction table | Your state vital records office', 'Title IV-D of the Social Security Act (42 U.S.C. sec. 666(a)(5)) -- voluntary acknowledgment and rescission requirements | Uniform Parentage Act (adopted in varying forms) | State paternity and disestablishment statutes.', 'VERIFIED', '2026-08-17', 'DO NOT SIGN A VOLUNTARY ACKNOWLEDGMENT OF PATERNITY WITHOUT CERTAINTY, AND IF IT WAS SIGNED IN ERROR, ACT INSIDE THE 60-DAY RESCISSION WINDOW. After that window it carries the force of a judgment and can generally only be attacked for fraud, duress, or material mistake -- and in many states not even then after a few years. Free genetic testing is available through the state child support agency in most states, before signing anything. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d9670a9b1629f9080ee888f4f9b1a326867e50448d05b3363ee6341ebcf2903f]', 'v1.0'),
('SAIS-FC-012', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_child_abuse_investigation', 'state', 'state -- ALL_STATES', 'Child Abuse Investigation -- Reporting, Agency Response, and Central Registry Findings', 'state_agency | law_enforcement', 'family_child_abuse_investigation', 'https://www.childhelphotline.org/', 'Childhelp National Child Abuse Hotline: 800-422-4453 (24/7) | Your state child abuse reporting hotline -- see jurisdiction table', 'Child Abuse Prevention and Treatment Act (42 U.S.C. sec. 5101 et seq.) | CAPTA reporter immunity and confidentiality provisions | Adam Walsh Act background check requirements | State mandatory reporting and central registry statutes.', 'VERIFIED', '2026-08-17', 'A SUBSTANTIATED REGISTRY FINDING IS SEPARATELY APPEALABLE AND THE DEADLINE IS SHORT. The absence of a criminal charge does not mean nothing was recorded. Read the finding letter for the appeal deadline the day it arrives and request the investigative file at the same time you file. On the reporting side: anyone may report, reports may generally be anonymous, and good faith reporters have statutory immunity in every state. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 893b66294a73f143a4e1521f27e4e4e65695e3127c49cfa889b8263c120d5af9]', 'v1.0'),
('SAIS-FC-013', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_preservation', 'federal + state', 'federal + state -- ALL_STATES', 'Family Preservation -- Prevention Services and the Reasonable Efforts Requirement', 'state_agency | community_organization', 'family_preservation', 'https://www.acf.hhs.gov/cb/title-iv-e-prevention-program', 'Your state child welfare agency prevention unit -- see jurisdiction table | Dial 211 for local family support services', 'Family First Prevention Services Act (Title IV-E, 42 U.S.C. sec. 671(e)) | Adoption and Safe Families Act reasonable efforts requirement (42 U.S.C. sec. 671(a)(15)) | Child Abuse Prevention and Treatment Act | State juvenile codes.', 'VERIFIED', '2026-08-17', 'ASK FOR PREVENTION SERVICES BY NAME AND CONTEST THE REASONABLE-EFFORTS FINDING ON THE RECORD. Family First prevention funding exists specifically to keep children home and is systematically underused. Where the underlying finding is neglect, identify whether the actual problem is material -- housing, utilities, childcare, food -- and route to those programs in parallel. Poverty is not neglect, but it is routinely processed as neglect when the material supports are not requested. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f5a6bc4cc35dbf78c4af92e4836fbd8701160ca7d8b878af28770b2da5b353dd]', 'v1.0'),
('SAIS-FC-014', 'systemic_abuse_intelligence', 29, 'family_and_children', 'family_kinship_care', 'federal + state', 'federal + state -- ALL_STATES', 'Kinship Care -- Relative Placement Preference, Licensing, and Financial Support', 'state_agency | federal_program', 'family_kinship_care', 'https://www.grandfamilies.org/', 'Your state child welfare kinship unit -- see jurisdiction table | Generations United kinship resources | Dial 211', 'Fostering Connections to Success and Increasing Adoptions Act (relative notice, 42 U.S.C. sec. 671(a)(29)) | Title IV-E guardianship assistance (42 U.S.C. sec. 673) | Kinship foster family licensing standards (45 CFR 1355) | Every Student Succeeds Act educational stability provisions.', 'VERIFIED', '2026-08-17', 'ASK ABOUT KINSHIP LICENSING AND ABOUT THE GUARDIANSHIP ASSISTANCE PROGRAM BY NAME, AND NEGOTIATE ANY ASSISTANCE AGREEMENT BEFORE FINALIZATION. The difference between informal kinship care and licensed kinship care is frequently several hundred dollars a month plus Medicaid and support services, and relatives are routinely placed informally without ever being told licensing was available. A guardianship or adoption assistance agreement not executed before finalization is generally lost permanently. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 6ba041f902ef65eb240519fc7900b1a53bd50f66d3b437a2d25723ce23a21f49]', 'v1.0'),
('SAIS-HI-001', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_health_insurance_denial', 'federal + state', 'federal + state -- ALL_STATES', 'Health Insurance Denial -- Two Stages, and the Second One Binds the Insurer', 'federal_agency | state_regulator', 'healthcare_health_insurance_denial', 'https://www.cms.gov/marketplace/private-health-insurance/external-appeals', 'DOL Employee Benefits Security Administration: 866-444-3272 | Your state Department of Insurance -- see jurisdiction table', 'ERISA (29 U.S.C. sec. 1001; 29 CFR 2560.503-1) | ACA internal appeals and external review (42 U.S.C. sec. 300gg-19; 45 CFR 147.136) | Mental Health Parity and Addiction Equity Act (29 U.S.C. sec. 1185a) | No Surprises Act (42 U.S.C. sec. 300gg-111)', 'VERIFIED', '2026-08-17', 'REQUEST THE COMPLETE CLAIM FILE AND THE SPECIFIC CLINICAL CRITERIA IN WRITING BEFORE DRAFTING THE APPEAL -- both are free under the ERISA claims rule. Then appeal against the actual criterion rather than against the summary denial letter. File a parallel complaint with your state Department of Insurance; regulator complaints are separately docketed and frequently move plans that appeals alone do not. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: d607da695f48e4020c428216f0bc41cfbb9a9c660d3a06f89ef3aef1ce6dbb4c]', 'v1.0'),
('SAIS-HI-002', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_hospital_billing_fraud', 'federal + state', 'federal + state -- ALL_STATES', 'Hospital Billing -- Itemized Review, Upcoding, and Mandatory Financial Assistance', 'federal_agency | state_attorney_general | nonprofit_hospital', 'healthcare_hospital_billing_fraud', 'https://oig.hhs.gov/fraud/report-fraud/', 'HHS Office of Inspector General Hotline: 800-447-8477 | CMS: 800-633-4227 | Your state AG -- see jurisdiction table', 'Affordable Care Act sec. 9007 / IRC sec. 501(r) (nonprofit hospital financial assistance, limitation on charges, 240-day application period) | No Surprises Act (42 U.S.C. sec. 300gg-111 et seq.) | False Claims Act (31 U.S.C. sec. 3729) | HIPAA right of access (45 CFR 164.524)', 'VERIFIED', '2026-08-17', 'REQUEST THE ITEMIZED BILL AND THE FINANCIAL ASSISTANCE POLICY IN THE SAME WRITTEN REQUEST, AND APPLY EVEN IF THE BILL IS ALREADY IN COLLECTION. Nonprofit hospitals must generally accept financial assistance applications for 240 days after the first billing statement, and must limit what financially eligible patients are charged. Patients routinely pay bills they were legally entitled to have reduced or eliminated because nobody told them the policy existed. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: aebf08be6795897c826fd8321416475ebe3f1fd384fdf1123654e62c93eabeda]', 'v1.0'),
('SAIS-HI-003', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_pharmacy_error', 'federal + state', 'federal + state -- ALL_STATES', 'Pharmacy Error -- Preserving Evidence and the Board of Pharmacy Track', 'state_licensing_board | federal_agency', 'healthcare_pharmacy_error', 'https://www.fda.gov/safety/medwatch-fda-safety-information-and-adverse-event-reporting-program', 'FDA MedWatch: 800-332-1088 | Institute for Safe Medication Practices | Your state Board of Pharmacy -- see jurisdiction table', 'Omnibus Budget Reconciliation Act of 1990 patient counseling requirements (42 U.S.C. sec. 1396r-8) | Federal Food, Drug, and Cosmetic Act (21 U.S.C. sec. 301 et seq.) | FDA adverse event reporting (21 CFR Part 314) | State pharmacy practice acts.', 'VERIFIED', '2026-08-17', 'DO NOT RETURN THE MEDICATION OR THE BOTTLE. Photograph the label and contents, then keep everything. This is the one piece of evidence that cannot be recreated and pharmacies routinely request its return as part of resolving the error. Poison Control at 800-222-1222 is free, staffed 24 hours by clinicians, and is the correct first call for the clinical question regardless of what happens with the complaint. [address_resolution: Resolve via the state board''s published office address; single statewide location in most states. Input = state only.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: eb22a02a50bf85a37e68c92f5c66049ab5d8b6c6f490b69027ad1e5268d6b05e]', 'v1.0'),
('SAIS-HI-004', 'systemic_abuse_intelligence', 38, 'healthcare_and_insurance', 'healthcare_medical_device_failure', 'federal', 'federal -- NATIONWIDE', 'Medical Device Failure -- Reporting, the Preemption Question, and Evidence', 'federal_agency | manufacturer', 'healthcare_medical_device_failure', 'https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfmaude/search.cfm', 'FDA MedWatch: 800-332-1088 | FDA Device Safety | CDRH Consumer line', 'Federal Food, Drug, and Cosmetic Act, Medical Device Amendments (21 U.S.C. sec. 360c et seq.) | Express preemption provision (21 U.S.C. sec. 360k) | Medical Device Reporting (21 CFR Part 803) | Recall regulations (21 CFR Part 806) | Riegel v. Medtronic (PMA preemption)', 'VERIFIED', '2026-08-17', 'ASK THE FACILITY IN WRITING TO PRESERVE THE EXPLANTED DEVICE BEFORE THE PROCEDURE. This single sentence, sent before surgery, is the difference between a provable case and an unprovable one. Then search the FDA MAUDE database for the same device model -- prior adverse event reports establish manufacturer notice and are free and public. Determine the PMA-versus-510(k) pathway early; it governs which claims federal law leaves available. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0c8c35312fb0484d63cab50eb40c6489949c08bc699e208f065c19d6bba7f0a7]', 'v1.0')
